    w = len(grid[0]) if h else 0

    def find_block():
        for r in range(h - 2):
            for c in range(w - 2):
                ok = True
                for dr in range(3):
                    for dc in range(3):
                        val = 3 if (dr == 1 and dc == 1) else 2
                        if grid[r + dr][c + dc] != val:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    return r + 1, c + 1  # center
        return None

    center = find_block()
    if center is None:
        return [row[:] for row in grid]

    r, c = center

    # Count visible 3-markers along the center row/column outside the 3x3 block.
    left = right = up = down = 0

    cc = c - 2
    while cc >= 0:
        if grid[r][cc] == 3:
            left += 1
        cc -= 2

    cc = c + 2
    while cc < w:
        if grid[r][cc] == 3:
            right += 1
        cc += 2

    rr = r - 2
    while rr >= 0:
        if grid[rr][c] == 3:
            up += 1
        rr -= 2

    rr = r + 2
    while rr < h:
        if grid[rr][c] == 3:
            down += 1
        rr += 2

    # Determine axis and direction.
    dr = dc = 0
    horizontal_present = (left + right) > 0
    vertical_present = (up + down) > 0

    if horizontal_present and not vertical_present:
        if right > left:
            dc = 2
        elif left > right:
            dc = -2
    elif vertical_present and not horizontal_present:
        if down > up:
            dr = 2
        elif up > down:
            dr = -2
    else:
        # Fallback: choose the axis with more markers; if tied, do not move.
        if (left + right) > (up + down):
            if right > left:
                dc = 2
            elif left > right:
                dc = -2
        elif (up + down) > (left + right):
            if down > up:
                dr = 2
            elif up > down:
                dr = -2

    nr, nc = r + dr, c + dc

    out = [row[:] for row in grid]

    # Remove old block, restoring the center marker.
    for rr in range(r - 1, r + 2):
        for cc in range(c - 1, c + 2):
            out[rr][cc] = 0
    out[r][c] = 3

    # Draw moved block.
    for rr in range(nr - 1, nr + 2):
        for cc in range(nc - 1, nc + 2):
            out[rr][cc] = 2
    out[nr][nc] = 3

    return out

